From f517e8b307d32bbbdb6ac51cacebfcc7a717e970 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:09:54 +0100
Subject: [PATCH] server: drop a removed default device before its row goes
 away

Removing the default device announced the default change while models
were halfway through removing its row, so applet radio buttons could
lose track of their device and stay checked; clear it beforehand now.

BUG: 500968
---
 src/server.cpp | 17 +++++++++++++++--
 1 file changed, 15 insertions(+), 2 deletions(-)

diff --git a/src/server.cpp b/src/server.cpp
index 7705c6d..77d1bc4 100644
--- a/src/server.cpp
+++ b/src/server.cpp
@@ -24,9 +24,22 @@ Server::Server(Context *context)
     Q_ASSERT(context);

     connect(&context->d->m_sinks, &MapBaseQObject::added, this, &Server::updateDefaultDevices);
-    connect(&context->d->m_sinks, &MapBaseQObject::removed, this, &Server::updateDefaultDevices);
     connect(&context->d->m_sources, &MapBaseQObject::added, this, &Server::updateDefaultDevices);
-    connect(&context->d->m_sources, &MapBaseQObject::removed, this, &Server::updateDefaultDevices);
+
+    // Drop a default device before the models start removing its row. Announcing the change in the middle of the
+    // removal makes views read the other devices at row indexes that are already out of date.
+    connect(&context->d->m_sinks, &MapBaseQObject::aboutToBeRemoved, this, [this, context](int index) {
+        if (context->d->m_sinks.objectAt(index) == d->m_defaultSink) {
+            d->m_defaultSink = nullptr;
+            Q_EMIT defaultSinkChanged(d->m_defaultSink);
+        }
+    });
+    connect(&context->d->m_sources, &MapBaseQObject::aboutToBeRemoved, this, [this, context](int index) {
+        if (context->d->m_sources.objectAt(index) == d->m_defaultSource) {
+            d->m_defaultSource = nullptr;
+            Q_EMIT defaultSourceChanged(d->m_defaultSource);
+        }
+    });

     // WirePlumber detection works based on connected clients.
     // Since we act on individual client changes let's compress them otherwise we may be switching state multiple times
